INSERT INTO Audit.Process_Config (Process_Code, Process_Name, Process_Desc, Process_Parameters, Process_Category_Code, Process_Type_Code) VALUES ('POSTRUN_RI_CHECK', 'Audit.usp_Check_Referential_Integrity', 'Post-run referential-integrity + sentinel gate. Runs AFTER all loads (NOT in the DAG -- category POSTRUN_GATE excludes it from the waves). THROWs on any orphaned fact fk or missing dim -1 sentinel so ETL_Run_Process logs FAILED and the build skips the semantic-model refresh. See Audit.RI_Check_Result.', '@Mode = ''LIVE'', @Logging = 1', 'POSTRUN_GATE', 'PROCEDURE');
